#!/usr/bin/env python3
"""Create a Markdown handbook and a standalone HTML course from the actual lesson data."""
from pathlib import Path
import json,html,shutil,argparse
R=Path(__file__).resolve().parents[2];L=json.loads((R/'lib/system-design/lessons.json').read_text());M=json.loads((R/'lib/system-design/media.json').read_text());OUT=R/'public/learn/system-design'
md=['# Sukoaa system design course','25 concepts: simple explanations, engineering trade-offs, narrated animations and interview practice.','The screenshot supplies the topic list. All explanations, fictional SeatSpot examples, diagrams and practice prompts are original teaching material. They are not claimed employer questions.','## How to study','Spend around 20–35 minutes per topic: explain the analogy, pause the animation and predict the next step, work the numerical example, try the exercise, then answer the interview prompts before checking the reference. Completion and interview rubrics are self-assessment, not AI grading.','## Foundations','A client asks; a server processes requests; an API defines an interaction; a database stores records. Networks can delay, duplicate or lose communication. Latency is time per operation; throughput is completed work per time. Tail percentiles differ from averages. Idempotency preserves one intended logical effect across repetitions. Consistency describes allowed observations of data.','## Topics']
for i,l in enumerate(L):md.append(f'{i+1}. {l["title"]}')
for i,l in enumerate(L):
 md += [f'\n## {i+1}. {l["title"]}',l['simple'],'### Everyday explanation',l['analogy'],'### SeatSpot scenario',l['why'],'### Engineering detail',*l['engineering'],'### Worked example',l['worked']['scenario'],l['worked']['calculation'],l['worked']['decision'],'### Implementation sketch',f'```{l["implementation"]["language"]}\n{l["implementation"]["code"]}\n```',l['implementation']['explanation'],'### Where it is used',*['- '+x for x in l['useCases']],'### Common mistakes',*['- '+x for x in l['pitfalls']],'### Exercise',l['exercise']['prompt'],*['Hint: '+x for x in l['exercise']['hints']],'Solution: '+l['exercise']['solution'],'### Interview practice']
 for q in l['interview']:md += ['**'+q['question']+'**',q['answer'],'Follow-up: '+q['followUp']]
 md += ['### Check your understanding',l['quiz']['question'],*[f'{j+1}. {x}' for j,x in enumerate(l['quiz']['options'])],f'Correct option: {l["quiz"]["correct"]+1}. '+l['quiz']['explanation'],'### Animation transcript']
 for s in l['flow']['steps']:md += ['**'+s['title']+'**',s['detail']]
 md += ['### Official references',*['- ['+x['title']+']('+x['url']+')' for x in l['references']]]
md += ['\n## Capstone: design a ticket sale','Start with 100 browsing requests/second and 5 booking attempts/second. Grow to 2,000 browsing requests/second and 100 booking attempts/second for ten minutes. Specify assumptions, latency and availability objectives, a seat-ownership invariant, storage and traffic estimates. Add components only when a requirement justifies them.','Inject one-zone loss and a lost payment response. Explain idempotency, pending state, concurrency limits, observability and recovery. For regional recovery, define RTO/RPO, write ownership, fencing, lag and failback. All numbers are fictional exercises, not benchmarks.','## Interview self-check','Clarify requirements; estimate with units; draw a request and data path; explain a failure; defend latency/cost/consistency/recovery trade-offs; name evidence and tests. Early-career practice: correct path and one failure. Mid-level: capacity and idempotency. Senior: ownership, migration, correlated failure and operating cost. These are practice levels, not promises about a particular employer.','## Media and privacy','MP4 clips contain offline computer-generated English narration (Flite SLT), animated architecture paths and readable captions. VTT caption files and transcripts accompany them. Videos are conceptual illustrations, not recordings of real clusters. No source-image portrait, music or social-media video was reused. Progress and notes in the integrated website are stored locally; export them before clearing browser storage.']
(OUT/'course-guide.md').write_text('\n\n'.join(md)+'\n')
# Offline HTML is generated from exactly the same content. It needs no npm, account or server.
parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--output',type=Path,required=True,help='Destination for the standalone offline course');dest=parser.parse_args().output;dest.mkdir(parents=True,exist_ok=True);(dest/'videos').mkdir(exist_ok=True)
css='body{font:17px/1.8 system-ui,sans-serif;color:#1c3040;background:#f7fafc;margin:0}header{background:#071e36;color:white;padding:28px max(22px,calc((100% - 960px)/2))}main{max-width:960px;margin:auto;padding:24px}h1,h2,h3{line-height:1.3}a{color:#075e60}header a{color:#a4efef}video{width:100%;aspect-ratio:16/9;background:#071e36}pre{overflow:auto;background:#0b2439;color:#e9f4fa;padding:20px;font:14px/1.7 monospace;border-radius:7px}details{border:1px solid #cbdce3;padding:12px 18px;margin:18px 0;border-radius:7px}summary{cursor:pointer;min-height:44px}li{margin:10px 0}p{max-width:75ch}:focus-visible{outline:3px solid #087d97;outline-offset:3px}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}'
e=html.escape
for i,l in enumerate(L):
 body=f'<header><a href="index.html">Sukoaa system design course</a><h1>{i+1}. {e(l["title"])}</h1></header><main><p>{e(l["simple"])}</p><video controls preload="none" poster="videos/{l["id"]}.jpg"><source src="videos/{l["id"]}.mp4" type="video/mp4"><track kind="captions" src="videos/{l["id"]}.vtt" srclang="en" label="English" default></video><p>Computer-generated English narration. Conceptual animation, not a live-system recording.</p><h2>Everyday explanation</h2><p>{e(l["analogy"])}</p><h2>Where it fits</h2><p>{e(l["why"])}</p><h2>Engineering detail</h2>'
 body+=''.join('<p>'+e(x)+'</p>' for x in l['engineering']);body+='<h2>Worked example</h2>'+''.join('<p>'+e(x)+'</p>' for x in l['worked'].values())
 body+=f'<h2>Implementation sketch</h2><pre><code>{e(l["implementation"]["code"])}</code></pre><p>{e(l["implementation"]["explanation"])}</p><h2>Common mistakes</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in l['pitfalls'])+'</ul>'
 body+='<h2>Exercise</h2><p>'+e(l['exercise']['prompt'])+'</p><details><summary>Hints and worked solution</summary>'+''.join('<p>Hint: '+e(x)+'</p>' for x in l['exercise']['hints'])+'<p>'+e(l['exercise']['solution'])+'</p></details><h2>Interview practice</h2>'
 for q in l['interview']:body+='<h3>'+e(q['question'])+'</h3><details><summary>Reference answer and follow-up</summary><p>'+e(q['answer'])+'</p><p>Follow-up: '+e(q['followUp'])+'</p></details>'
 body+='<h2>Knowledge check</h2><p>'+e(l['quiz']['question'])+'</p><ol>'+''.join('<li>'+e(x)+'</li>' for x in l['quiz']['options'])+'</ol><details><summary>Answer</summary><p>'+str(l['quiz']['correct']+1)+'. '+e(l['quiz']['explanation'])+'</p></details><h2>Full animation transcript</h2>'
 for s in l['flow']['steps']:body+='<h3>'+e(s['title'])+'</h3><p>'+e(s['detail'])+'</p>'
 body+='<h2>Official references</h2><ul>'+''.join('<li><a href="'+e(x['url'],quote=True)+'">'+e(x['title'])+'</a></li>' for x in l['references'])+'</ul><p><a href="index.html">Back to all topics</a></p></main>'
 (dest/f'{l["id"]}.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(l['title'])+' | Sukoaa</title><style>'+css+'</style>'+body+'</html>')
 for ext in ['mp4','vtt','jpg']:shutil.copy2(OUT/f'{l["id"]}.{ext}',dest/'videos'/f'{l["id"]}.{ext}')
index='<header><h1>Sukoaa system design course</h1><p>25 topics, narrated animations, worked examples and interview practice.</p></header><main><h2>How to learn</h2><p>Open one lesson. Explain the analogy, pause the animation to predict a step, work the exercise and practise an answer before revealing the reference. Plan about 20–35 minutes per lesson. Use the complete Markdown handbook for prerequisites and a capstone. All examples are fictional; this is self-guided study.</p><p><a href="course-guide.md">Complete course handbook</a></p><ol>'+''.join('<li><a href="'+l['id']+'.html">'+e(l['title'])+'</a></li>' for l in L)+'</ol><p>Extract the ZIP before opening index.html. Offline pages do not upload data and require no npm installation. Local progress/notes and the timed mentor interface are available in the integrated Sukoaa Next.js course.</p></main>'
(dest/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>System design tutorials | Sukoaa</title><style>'+css+'</style>'+index+'</html>');shutil.copy2(OUT/'course-guide.md',dest/'course-guide.md')
print('Handbook and offline HTML/video course generated.')

if (OUT/"MEDIA-NOTICES.txt").exists():shutil.copy2(OUT/"MEDIA-NOTICES.txt",dest/"MEDIA-NOTICES.txt")
